MOUTH_GAG_BLOCKING = [
    "ball gag", "bit gag", "tape gag", "panel gag", "cloth gag",
    "large ball gag", "rubber bit gag", "cleave gag",
    "inflatable gag", "penis gag", "harness gag with a ball",
    "leather panel gag strapped tight",
]

MUZZLE_GAG_ONLY = ["muzzle gag", "leather muzzle"]

ORAL_ACT_PATTERN = re.compile(
    r"\bfellatio\b|\bdeepthroat\b|\birrumatio\b|\bblowjob\b|oral insertion|"
    r"mouth insertion|cum in mouth|forced feeding|forced drinking|water feeding|"
    r"pee in mouth|drinking pee|urine in mouth|peeing in mouth|\bin mouth\b|"
    r"in throat|down (his|her|their) throat",
    re.IGNORECASE
)
PUPPY_PLAY_PATTERN = re.compile(r"\bpuppy play\b|\bpet play\b|human dog", re.IGNORECASE)

DROOL_VARIANTS = [
    "saliva dripping from the corner of the mouth",
    "drool leaking around the gag",
    "thick saliva strings hanging from the chin",
    "drool pooling beneath the chin",
    "saliva glistening on the lips",
]
CUM_WITH_GAG_VARIANTS = [
    "cum dripping down the chin past the gag",
    "cum on the face around the gag straps",
    "cum mixing with saliva on the chin",
    "cum smeared across the cheek near the gag",
]

def inject_mouth_gag(action_text, mode):
    """
    Systeme logique de gag : ring gag / muzzle gag / spider gag laissent
    la bouche accessible et sont compatibles avec fellatio/insertion
    buccale. Ball gag / bit gag / tape gag REMPLISSENT ou BLOQUENT la
    bouche -- incompatibles avec un acte oral en cours (contradiction
    physique). Le muzzle gag est privilegie en contexte puppy/pet play.

    Ajoute aussi automatiquement de la salive (et du cum si l'acte le
    justifie) quand un gag est present, pour un rendu coherent plutot
    que le gag seul sans consequence visible.
    """
    if not action_text or mode not in ("hard", "extreme"):
        return ""
    at = action_text.lower() if isinstance(action_text, str) else "{}".format(action_text).lower()

    has_oral = bool(ORAL_ACT_PATTERN.search(at))
    has_puppy = bool(PUPPY_PLAY_PATTERN.search(at))

    if random.random() > (0.5 if mode == "extreme" else 0.35):
        return ""

    if has_oral:
        # Jamais de ball/bit/tape gag pendant un acte oral : contradiction
        # physique (la bouche est deja occupee/ouverte pour l'acte).
        gag = random.choice(MOUTH_GAG_ORAL_COMPATIBLE)
    elif has_puppy:
        gag = random.choice(MUZZLE_GAG_ONLY)
    else:
        # Hors contexte oral : tous les gags sont valides, y compris
        # ceux qui bloquent completement la bouche.
        gag = random.choice(MOUTH_GAG_ORAL_COMPATIBLE + MOUTH_GAG_BLOCKING)

    parts = [gag]

    # Salive automatique si le gag laisse la bouche ouverte/accessible
    is_open_type = gag in MOUTH_GAG_ORAL_COMPATIBLE or gag in MUZZLE_GAG_ONLY
    if is_open_type and random.random() < 0.6:
        parts.append(random.choice(DROOL_VARIANTS))
        if has_oral and re.search(r"cum|facial|ejaculat", at) and random.random() < 0.5:
            parts.append(random.choice(CUM_WITH_GAG_VARIANTS))

    return ", ".join(parts)


