def get_lighting(mode):
    """
    Éclairage plus chaleureux et varié selon le mode.
    Plus de lumière tamisée, chaude et décorative.
    """

    if mode == "romance":
        # Forte préférence pour lumière chaude / tamisée / romantique
        lighting_pool = (
            WARM_LIGHTING * 3 +
            DIM_NIGHT_LIGHTING * 2 +
            ROMANTIC_LIGHTING * 3 +
            DECORATIVE_WALL_LIGHTING * 2
        )
        return random.choice(lighting_pool)

    elif mode == "soft":
        lighting_pool = (
            WARM_LIGHTING * 2 +
            DIM_NIGHT_LIGHTING * 2 +
            ROMANTIC_LIGHTING +
            DECORATIVE_WALL_LIGHTING
        )
        return random.choice(lighting_pool)

    elif mode == "hard":
        # Plus de lumière tamisée / contrastée
        lighting_pool = DIM_NIGHT_LIGHTING + WARM_LIGHTING + DECORATIVE_WALL_LIGHTING
        return random.choice(lighting_pool)

    else:  # extreme
        # Plus sombre et contrasté
        lighting_pool = (
            DIM_NIGHT_LIGHTING * 2 +
            ["moody lighting", "dramatic lighting", "low key lighting"] +
            DECORATIVE_WALL_LIGHTING
        )
        return random.choice(lighting_pool)
    
