def extract_char_count(gender_str):
    matches = re.findall(r'(\d+)(boy|girl)', gender_str)
    return sum(int(count) for count, _ in matches) if matches else 1


MIRROR_PATTERN = re.compile(r"\bmirror\b|own reflection", re.IGNORECASE)

# Le probleme concret : sans indication, le modele traite le reflet comme un
# SECOND personnage et produit deux corps de face. Trois signaux ensemble
# reglent ca :
#   1. (reflection:1.3)      -> tag Danbooru reconnu, le modele sait qu'il y a
#                               une surface reflechissante
#   2. (mirror:1.2)          -> ancre l'objet miroir dans la scene
#   3. la phrase descriptive -> precise que le reflet montre LE MEME corps vu
#                               du cote oppose, pas quelqu'un d'autre
MIRROR_REFLECTION_TAG = (
    "(reflection:1.3), (mirror:1.2), "
    "the mirror shows the same person from the opposite side, "
    "reversed reflection of the same body"
)

def add_mirror_reflection(text):
    """
    Ajoute les tags de reflet quand la pose mentionne un miroir sans les avoir.
    Sans ca, le reflet est rendu comme un second personnage distinct.
    """
    if not text or not MIRROR_PATTERN.search(str(text)):
        return text
    if re.search(r"\breflection\b|\breflected\b", str(text), re.IGNORECASE):
        return text
    return f"{text}, {MIRROR_REFLECTION_TAG}"


FURNITURE_CONFLICT = re.compile(
    r"\b(computer chair|gaming chair|office chair|desk chair|armchair|arm chair|"
    r"sofa|couch|beanbag|bean bag|pouf|ottoman|hammock|egg chair|window seat|"
    r"stool|bench|rug|floor cushion|carpet|chest|desk|table|vanity|wheelchair|"
    r"examination table|treatment chair|recovery chair|shower chair)\b",
    re.IGNORECASE
)
BED_WORD = re.compile(r"\b(on the bed|on the mattress|bed|mattress|headboard|bedframe)\b",
                      re.IGNORECASE)

def strip_conflicting_bed(text):
    """
    Si la position nomme un autre meuble (chaise, pouf, hamac...), le mot 'bed'
    present ailleurs dans le prompt prend le dessus et le modele place tout sur
    le lit. On retire donc les mentions de lit dans ce cas.
    """
    if not text or not FURNITURE_CONFLICT.search(str(text)):
        return text
    segs = [s.strip() for s in str(text).split(",")]
    kept = []
    for s in segs:
        if BED_WORD.search(s) and not FURNITURE_CONFLICT.search(s):
            continue
        kept.append(s)
    return ", ".join([s for s in kept if s])

def deduplicate_tags(prompt_str):
    if not prompt_str:
        return ""
    tags = [tag.strip() for tag in prompt_str.split(',') if tag.strip()]
    seen = set()
    unique = []
    for t in tags:
        key = t.lower()
        if key not in seen:
            seen.add(key)
            unique.append(t)
    return ", ".join(unique)


