def ensure_leading_tag(pos):
    """
    Toute position doit commencer par un tag pondere "(mot:poids)" pour
    ancrer clairement le sujet principal au debut du prompt. Si aucun
    tag n'est present, en detecte un pertinent depuis le contenu plutot
    que de supprimer une entree par ailleurs valide.
    """
    if not pos:
        return ""
    if re.match(r'^\([a-z0-9_\'\- ]+:[\d.]+\)', pos, re.I):
        return ""  # deja un tag en tete, rien a faire
    for pattern, tag in MISSING_LEADING_TAG_MAP:
        if pattern.search(pos):
            weight = round(random.uniform(1.1, 1.3), 2)
            return f"({tag}:{weight})"
    # Avant de tomber sur kissing par defaut, verifier si c'est en fait
    # une scene de contrainte pure (collier/harnais/menottes/spreader bar
    # sans contact romantique) -- "kissing" n'a aucun sens pour ce genre
    # de contenu, "bondage" est bien plus coherent avec le reste.
    if re.search(r"\bcollar\b|\bharness\b|\bcuff\w*\b|\bspreader bar\b|\bwrists?\b|\bshackle", pos, re.I):
        weight = round(random.uniform(1.1, 1.3), 2)
        return f"(bondage:{weight})"
    weight = round(random.uniform(1.1, 1.3), 2)
    return f"(kissing:{weight})"


