# ============================================================
# FONCTION DE PIOCHAGE
# ============================================================
def get_expressions_from_orders(orders: list, count_per_pool: int = 1,
                                avoid_global_duplicates: bool = True) -> dict:
    """
    Pioche des expressions faciales selon des ordres définis pour chaque personnage.
    """
    result = {}
    used_global = set()

    for person_idx, person_order in enumerate(orders):
        person_expressions = []

        for pool_name in person_order:
            pool = EXPRESSION_POOLS.get(pool_name, EXPRESSIONS_SOFT)
            if not pool:
                continue

            if avoid_global_duplicates:
                available = [expr for expr in pool if expr not in used_global]
            else:
                available = pool.copy()

            if len(available) < count_per_pool:
                chosen = available
            else:
                chosen = random.sample(available, count_per_pool)

            person_expressions.extend(chosen)
            used_global.update(chosen)

        result[person_idx] = person_expressions

    return result


