def parse_gender_string(gender_str: str) -> list:
    """
    Extrait les descriptions de personnages à partir de la chaîne gender.
    Exemple: "1girl, 2boys" -> ["1girl", "2boys"]
    """
    if not gender_str:
        return []
    return [p.strip() for p in gender_str.split(',') if p.strip()]


def get_orders_for_mode(mode: str, nb_persons: int) -> list:
    """
    Retourne une liste d'ordres (pools) pour chaque personnage.
    CHAQUE personnage pioche dans 1 ou 2 pools différents pour avoir
    au moins 2 à 3 expressions faciales distinctes.
    """
    # Définition des ordres de base (répartis pour varier)
    if mode == "romance":
        base_orders = [
            ["romance", "soft"],   # perso 1 : romance + soft
            ["romance", "soft"],   # perso 2 : romance + soft (retire "pain" -- ne devrait jamais lire de la detresse en romance)
            ["romance"],           # perso 3 : romance uniquement (mais 2 tags car count=2)
            ["romance", "romance"],# perso 4 : double romance (2 tags)
        ]
    elif mode == "soft":
        base_orders = [
            ["soft", "romance"],
            ["soft", "hard"],      # retire "pain" (ne colle pas au ton doux)
            ["soft"],
            ["soft", "soft"],
        ]
    elif mode == "hard":
        base_orders = [
            ["hard", "pain"],
            ["hard", "soft"],      # NOUVEAU : croisement occasionnel vers soft, demande pour eviter la monotonie
            ["hard", "hard"],
            ["hard", "pain"],
        ]
    elif mode == "extreme":
        # Avant : 2 des 4 personnages piochaient une combinaison
        # majoritairement detresse ("extreme" seul ou "extreme"+"pain"),
        # donc un groupe de 4 finissait souvent avec tout le monde en
        # pleurs/terreur meme si chaque MOT etait different (le probleme
        # n'est pas la repetition de mot mais l'uniformite thematique).
        # Desormais seul 1 personnage sur 4 reste sur une combinaison
        # lourde en detresse ; les autres melangent vers hard/anger
        # (intensite, dominance) qui restent coherents avec extreme
        # sans faire pleurer tout le monde a la fois.
        base_orders = [
            ["extreme", "hard"],
            ["hard", "extreme"],
            ["extreme", "anger"],
            ["extreme", "pain"],
        ]
    else:
        base_orders = [["soft"]]

    # On répète l'ordre en boucle pour le nombre de personnages
    orders = []
    for i in range(nb_persons):
        orders.append(base_orders[i % len(base_orders)])
    return orders


# ============================================================
# FONCTION PRINCIPALE : inject_facial_expression (REFONTE)
# ============================================================
def inject_facial_expression(mode: str, weighted_action: str = "", gender: str = "") -> str:
    """
    Génère une chaîne d'expressions faciales DISTINCTES pour chaque personnage.
    Chaque personnage reçoit DÉSORMAIS entre 2 et 4 tags d'expressions.
    """
    if not gender:
        return "blush, open mouth"

    person_descs = parse_gender_string(gender)
    nb_persons = len(person_descs)

    if nb_persons == 0:
        return "blush, open mouth"

    # Récupérer les ordres (pools) pour chaque personnage
    orders = get_orders_for_mode(mode, nb_persons)

    # 🔥 NOUVEAU : on prend PLUS d'expressions par pool
    # - romance/soft : 2 tags par pool
    # - hard/extreme : 3 tags par pool (pour plus d'intensité)
    if mode in ("hard", "extreme"):
        count_per_pool = 3
    else:
        count_per_pool = 2

    # Piocher les expressions
    exprs_dict = get_expressions_from_orders(
        orders,
        count_per_pool=count_per_pool,
        avoid_global_duplicates=True
    )

    # Construire la chaîne finale: "1girl: happy, blush, smile; 1boy: crying, tears"
    expr_parts = []
    for i, desc in enumerate(person_descs):
        exprs = exprs_dict.get(i, [])

        # Si le personnage a moins de 2 expressions, on lui en ajoute
        if len(exprs) < 2:
            # Fallback intelligent selon le mode
            if mode in ("hard", "extreme"):
                fallback = ["blush", "open mouth"]
            elif mode == "romance":
                fallback = ["blush", "smile"]
            else:
                fallback = ["blush", "calm expression"]

            # Garder ce qu'on a et compléter
            exprs = exprs + fallback
            # Limiter à 5 tags max pour ne pas surcharger
            exprs = exprs[:5]

        expr_str = ", ".join(exprs)
        expr_parts.append(expr_str)

    # IMPORTANT : on ne prefixe PLUS par "{desc}:" (ex "3boys:").
    # Le modele relisait ce token comme un NOUVEAU groupe de personnages et
    # generait des clones statiques en plus de la scene. Les expressions sont
    # donc emises en tags simples, separes par des virgules.
    return ", ".join(expr_parts)

