def check_action_compatibility(text):
    """
    Outil de diagnostic : verifie un texte de position contre les
    regles connues et retourne une liste d'avertissements. Ne modifie
    rien automatiquement -- sert a scanner la base et reperer les
    memes classes de bugs qu'on a corrigees manuellement cette session
    (fellatio+gag bloquant, CBT position impossible, etc), sans avoir
    a repartir de zero a chaque audit.
    """
    warnings = []
    if not text:
        return warnings
    t = text.lower()

    if ("cbt" in t or "ball busting" in t):
        if POSE_DETECTION_PATTERNS["all_fours"].search(t) and POSE_DETECTION_PATTERNS["from_behind"].search(t):
            warnings.append("CBT/ball busting + all fours + from behind : testicules inaccessibles")

    if "fellatio" in t:
        for g in ACTION_COMPATIBILITY["fellatio"]["forbidden_with"]:
            if g in t:
                warnings.append(f"fellatio + {g} : bouche deja occupee")
        if "sitting on face" in t:
            warnings.append("fellatio + sitting on face : position impossible")

    if "69" in t and not re.search(r'head.to.groin|lying|kneeling|curled|straddl|reclin', t):
        warnings.append("69 sans position claire (tete-bassin non decrite)")

    if "bukkake" in t and ("shibari" in t or "full-body bondage" in t):
        warnings.append("bukkake + shibari/full-body bondage : immobilise tout le monde, verifier coherence")

    return warnings


CAMERA_TAG_PATTERN = re.compile(
    r"\((pov|pov looking down|pov between legs|first-person view|over-the-shoulder view|"
    r"close-up shot|extreme close-up|depth of field|"
    r"cowboy shot|knee-up shot|medium shot|waist-up shot|upper body|three-quarter shot|"
    r"medium two-shot|full-body shot|three-quarter full body|full-body two-shot|"
    r"low angle shot|high angle|side view|from behind|back view|from above|"
    r"from above looking down|from below|from below looking up|"
    r"front view|from front|eye level shot|"
    r"dutch angle|couple medium shot|couple full-body shot|facing each other medium shot|"
    r"side by side medium shot|two-shot medium|group medium shot|from the side|"
    r"wide shot|three-shot medium|four-shot medium|trio dynamic shot|"
    r"focused on one person, others in background|"
    r"standing out from the group, character in spotlight)\s*:",
    re.IGNORECASE
)

def position_has_camera(text):
    """La position contient-elle deja un cadrage ? Si oui le moteur n'en ajoute pas."""
    return bool(text) and bool(CAMERA_TAG_PATTERN.search(str(text)))


SELF_ACT_PATTERN = re.compile(r"\bautofellatio\b|\bautofacial\b|\bautocunnilingus\b|\bautopaizuri\b",
                              re.IGNORECASE)

def is_self_act(text):
    """Actes sur soi-meme : jamais de POV (cree un 2e personnage), jamais a 2+."""
    return bool(text) and bool(SELF_ACT_PATTERN.search(str(text)))

def get_allowed_framings(char_count: int, mode: str, use_pov_probability: float = 0.08, action_text: str = "") -> list:
    candidates = []

    # 1. Récupération des cadrages standards valides
    for f in FRAMING_STYLES_DATA:
        min_c = f.get("min_chars", 1)
        max_c = f.get("max_chars", 99)

        if min_c <= char_count <= max_c:
            candidates.append(f["style"])

    # Contradiction physique : "looking at viewer" + cadrage dos-au-spectateur
    # est impossible (on ne peut pas regarder le spectateur en lui tournant
    # le dos). Exclure ces cadrages si le texte dit deja looking at viewer.
    if action_text and re.search(r"\blooking at viewer\b", str(action_text), re.IGNORECASE):
        candidates = [c for c in candidates
                      if not any(c == f["style"] and "from behind" in f.get("tags", [])
                                 for f in FRAMING_STYLES_DATA)]

    # Scene devant un miroir : la camera face au personnage (front view,
    # looking at viewer) place le miroir hors champ ou dans le dos du
    # spectateur -- le reflet decrit dans le texte ne serait pas visible.
    # Privilegier les angles de cote/dos qui peuvent capturer le miroir.
    if action_text and re.search(r"\bmirror\b", str(action_text), re.IGNORECASE):
        candidates = [c for c in candidates
                      if not any(c == f["style"] and
                                 (f["style"].startswith("(front view") or
                                  f["style"].startswith("(from front") or
                                  "looking at viewer" in f["style"].lower())
                                 for f in FRAMING_STYLES_DATA)]

    # En contexte public, "from behind" cache le visage et le decor
    # environnant (foule, rue) qui fait tout l'interet de la scene --
    # sauf pour le jouet anal, ou l'angle reste necessaire pour voir
    # l'objet.
    if action_text and is_public_context(action_text):
        at_check = str(action_text).lower()
        is_anal_toy = re.search(r"anal (beads|hook|plug)|butt plug|dildo", at_check)
        if not is_anal_toy:
            candidates = [c for c in candidates
                          if not any(c == f["style"] and "from behind" in f.get("tags", [])
                                     for f in FRAMING_STYLES_DATA)]

    # 2. Récupération des styles POV valides selon le nombre de personnages
    pov_candidates = []
    for p in POV_STYLES_DATA:
        min_c = p.get("min_chars", 1)
        max_c = p.get("max_chars", 99)

        if min_c <= char_count <= max_c:
            pov_candidates.append(p["style"])

    # 3. POV : le tirage POV ne doit PAS court-circuiter le forcage de cadrage
    #    par la pose (etape 5). On memorise juste le choix ici et on le
    #    consomme plus bas, apres les regles imposees.
    # En solo, le POV cree un 2e "personnage" implicite (celui qui regarde) :
    # jamais de POV a 1 seul personnage.
    want_pov = char_count > 1 and bool(pov_candidates) and random.random() < use_pov_probability

    # 4. Fallback de sécurité si aucun candidat standard n'est trouvé
    if not candidates:
        if char_count >= 5:
            # waist-up/medium shot ne peuvent pas montrer 5-6 personnes
            # de facon coherente -- seuls des plans larges fonctionnent.
            candidates = [
                "(wide shot:1.3)",
                "(full-body shot:1.25)",
                "(group shot:1.3)",
            ]
        elif char_count >= 3:
            candidates = [
                "(medium shot:1.3)",
                "(waist-up shot:1.3)",
                "(dutch angle:1.2)"
            ]
        else:
            candidates = [
                "(cowboy shot:1.35)",
                "(medium shot:1.3)",
                "(three-quarter shot:1.25)",
                "(full-body shot:1.2)"
            ]

    # 5. CADRAGE IMPOSE PAR LA POSE
    #    Certaines poses n'ont de sens que sous un angle precis. Plutot que
    #    d'ecrire l'angle dans la position (ce qui entrerait en conflit avec
    #    le framing choisi ici), on detecte la pose et on filtre les cadrages
    #    compatibles. Un seul angle sort donc au final, jamais deux.
    if action_text:
        at = str(action_text).lower()

        # --- a0) Autofellatio : necessite un corps replie/visible en
        #     entier pour etre coherent -- jamais un cadrage serre
        #     (close-up, waist-up) qui ne montrerait pas la flexibilite.
        if re.search(r"\bautofellatio\b", at):
            wide = [c for c in candidates
                    if any(c == f["style"] and (f["style"].startswith("(cowboy shot")
                           or f["style"].startswith("(full-body")
                           or "full" in f.get("tags", []))
                           for f in FRAMING_STYLES_DATA)]
            if wide:
                return wide

        # --- a1) Objet sexuel visible DANS les fesses : from behind
        #     PREFERE (necessaire pour voir l'objet) mais plus jamais a
        #     100% -- on l'inclut plusieurs fois dans la liste (poids
        #     plus fort au tirage aleatoire) plutot que de le forcer seul.
        if re.search(r"anal (beads|hook|plug|object insertion)|"
                     r"butt plug|anal beads|anal hook|anal plug|tail plug|"
                     r"dildo|vibrator insertion", at):
            # Assis ou angle deja precise dans le texte -> ne pas forcer
            # back view, le from behind ne fait pas sens ou est redondant
            if re.search(r"\bsitting\b|\bseated\b|\bstraddl\w*\b", at):
                pool = None  # ne rien forcer, continuer vers la logique normale plus bas
            else:
                back = [c for c in candidates
                        if any(c == f["style"] and "from behind" in f.get("tags", [])
                               for f in FRAMING_STYLES_DATA)]
                other = [c for c in candidates
                         if any(c == f["style"] and
                                ("side" in f.get("tags", []) or
                                 f["style"].startswith("(from above") or
                                 f["style"].startswith("(three-quarter") or
                                 f["style"].startswith("(front") or
                                 f["style"].startswith("(from front") or
                                 f["style"].startswith("(full-body") or
                                 f["style"].startswith("(medium shot") or
                                 f["style"].startswith("(cowboy shot"))
                                for f in FRAMING_STYLES_DATA)]
                pool = back * 2 + other  # from behind pese 2x plus, jamais exclusif
            if pool:
                return pool

        # --- a2) Poses physiques (doggy, bent over, spanking, fingering,
        #     fisting, enema...) : angle libre parmi plusieurs options
        #     compatibles. Avant, doggy/bent over/spanking etaient forces
        #     a 100% en from behind -- ca marche visuellement mais casse
        #     la variete. Toutes les vues restent coherentes avec la
        #     pose (de face on voit l'expression du receveur, l'autre
        #     personnage derriere ; de cote on voit les deux corps).
        if re.search(r"doggy|prone bone|from behind|on all fours|bent over|"
                     r"spanking|paddling|caning|ass (up|raised|spread)|"
                     r"spreading (own )?(ass|cheeks)|presenting ass|"
                     r"anal (fingering|fisting)|\benema\b|\bfisting\b|"
                     r"prostate|speculum|object insertion", at):
            varied = [c for c in candidates
                      if any(c == f["style"] and
                             ("from behind" in f.get("tags", []) or
                              "side" in f.get("tags", []) or
                              f["style"].startswith("(from above") or
                              f["style"].startswith("(three-quarter") or
                              f["style"].startswith("(front") or
                              f["style"].startswith("(from front"))
                             for f in FRAMING_STYLES_DATA)]
            if varied:
                return varied

        #  b) poses tournees vers le fond du decor
        if re.search(r"facing the (backrest|headboard|wall)|"
                     r"back to the room|hands (gripping|on) the (backrest|top edge|push handles)|"
                     r"bracing both hands on the (dresser|counter)|arched forward|"
                     r"pressed against the (floor-to-ceiling window|window)", at):
            back = [c for c in candidates
                    if any(c == f["style"] and "from behind" in f.get("tags", [])
                           for f in FRAMING_STYLES_DATA)]
            if back:
                return back


        # --- anilingus : angles varies (side / three-quarter / low) ---
        if re.search(r"\banilingus\b|\brimming\b", at):
            ok = [c for c in candidates
                  if re.search(r"side view|three-quarter|low angle|from behind|from the side", c, re.I)]
            if ok:
                return ok
        # --- actes sur soi-meme : jamais de POV ni de cadrage a 2 ---
        if is_self_act(at):
            ok = [c for c in candidates
                  if not re.search(r"pov|first-person|over-the-shoulder|two-shot|couple|group", c, re.I)]
            if ok:
                return ok

        # --- vue plongeante ---
        if re.search(r"lying (flat|face down|on the back|back across|upside)|"
                     r"forehead (resting )?on the mattress|head tilted over the far edge|"
                     r"lying on the back in a wide hammock", at):
            above = [c for c in candidates if re.search(r"high angle|from above|full-body", c, re.I)]
            if above:
                return above

        # --- vue de profil ---
        if re.search(r"lying lengthwise|hammock|window seat|side-on|"
                     r"lying on the side|hips folded upward", at):
            side = [c for c in candidates
                    if any(c == f["style"] and "side" in f.get("tags", [])
                           for f in FRAMING_STYLES_DATA)]
            if side:
                return side

        # --- miroir : cadrage libre parmi les compatibles ---
        #  On ne force PAS un seul cadrage. On retire seulement ceux qui
        #  cassent la composition personnage + reflet (close-up, pov, angles
        #  extremes). Le tirage reste aleatoire parmi full-body / cowboy /
        #  medium shot / waist-up. Le reflet lui-meme est gere en aval par
        #  add_mirror_reflection().
        if re.search(r"\bmirror\b|own reflection", at):
            ok = [c for c in candidates
                  if re.search(r"full-body|cowboy shot|medium shot|waist-up|three-quarter", c, re.I)]
            if ok:
                return ok

        # --- detail rapproche (zones cum) ---
        if re.search(r"cum on (face|tongue|navel|pectorals|breasts|feet|armpits|hair|eyewear|fingers|pussy)|"
                     r"cum in mouth|autofacial", at):
            close = [c for c in candidates if re.search(r"close-up", c, re.I)]
            if close:
                return close

    # 6. Backview force pour l'insertion d'objet anal
    if action_text and re.search(r"anal (fingering|fisting|object insertion|insertion)", action_text, re.I):
        backview_candidates = [
            c for c in candidates
            if any(
                c == f["style"] and "from behind" in f.get("tags", [])
                for f in FRAMING_STYLES_DATA
            )
        ]
        if backview_candidates:
            return backview_candidates

    # POV consomme ici seulement : aucune regle de pose ne s'est appliquee
    if want_pov:
        return pov_candidates

    return candidates
