def action_implies_full_restraint(text):
    """
    Gear qui immobilise/couvre tout le corps (ex: straitjacket) -> le
    personnage doit etre automatiquement nu en dessous, porter des
    vetements normaux en plus n'a pas de sens visuellement.
    Liste volontairement conservatrice, a completer au besoin.
    """
    if not text:
        return False
    return bool(re.search(r"\bstraitjacket\b", str(text), re.I))

