def is_public_context(text):
    """Retourne True si le texte contient un mot-clé public."""
    if not text:
        return False
    if isinstance(text, (list, tuple)):
        text = " ".join(str(x) for x in text if x)
    text_lower = str(text).lower()
    for kw in PUBLIC_KEYWORDS:
        if kw in text_lower:
            return True
    return False


# "sex" seul, MAIS pas si deja precede de "anal " ou "vaginal " (evite le
# doublon "anal anal sex" / "vaginal vaginal sex" quand le mot "sex" fait
# deja partie d'un tag compose ajoute par une etape precedente du pipeline)
BARE_SEX_PATTERN = re.compile(r'(?<!anal )(?<!vaginal )(?<!group )\bsex\b(?!\s*slave)', re.IGNORECASE)
BARE_FISTING_PATTERN = re.compile(r'(?<!anal )(?<!vaginal )\bfisting\b', re.IGNORECASE)
BARE_FINGERING_PATTERN = re.compile(r'(?<!anal )(?<!vaginal )\bfingering\b', re.IGNORECASE)




def strip_matching_tag_from_context(weighted_action, context):
    """
    Retire du contexte le tag d'action principal deja extrait dans
    weighted_action, pour eviter la duplication dans le prompt final.
    """
    if not weighted_action or not context:
        return context
    match = re.search(r'\(([^:)]+):[0-9.]+\)', weighted_action)
    if not match:
        return context
    tag = match.group(1).strip()
    cleaned = re.sub(rf'\(\s*{re.escape(tag)}\s*:[0-9.]+\s*\)', '', context, flags=re.I)
    # Ne retire le mot nu QUE s'il est isole entre virgules/debut/fin --
    # jamais s'il fait partie d'une phrase ("giving fellatio", "fellatio
    # while..."), sinon la phrase perd son objet grammatical et devient
    # "giving," orpheline.
    cleaned = re.sub(rf'(^|,\s*){re.escape(tag)}(\s*,|$)', r'\1\2', cleaned, flags=re.I)
    cleaned = re.sub(r',\s*,', ',', cleaned)
    cleaned = re.sub(r'^[,\s]+|[,\s]+$', '', cleaned)
    return re.sub(r'\s+', ' ', cleaned).strip()

def select_environment(context, weighted_action, mode, prompt_text=""):
    """
    Retourne TOUJOURS une seule string de decor.
    Priorite :
      1) shower -> SHOWER_ENVIRONMENTS
      2) urine  -> URINE_ENVIRONMENTS (+ rooms adaptees)
      3) public -> PUBLIC_ENVIRONMENTS
      4) sinon  -> pool du mode melange avec ROOM_THEMES
    """
    test_text = f"{weighted_action} {context} {prompt_text}".lower()

    if is_shower_context(test_text):
        pool = list(SHOWER_ENVIRONMENTS)

    elif is_urine_context(test_text):
        # Elargi : avant, seulement URINE_ENVIRONMENTS + un sous-ensemble
        # tres etroit de ROOM_THEMES (mots-cles toilet/drain/etc), ce qui
        # rendait la scene redondante (toujours une salle de bain/toilette).
        # Desormais on pioche aussi dans ROOM_THEMES au complet, dans
        # HARD_ENVIRONMENTS et dans WATER_LOCATIONS_DECOR (piscine, spa,
        # sauna -- pas juste douche/toilette).
        pool = list(URINE_ENVIRONMENTS) + list(ROOM_THEMES) + list(HARD_ENVIRONMENTS) + list(WATER_LOCATIONS_DECOR)

    elif is_water_torture_context(test_text):
        # water torture / forced drinking / forced feeding ne
        # declenchaient rien avant -> decor totalement aleatoire, parfois
        # une chambre romantique cosy pour une scene de torture a l'eau.
        # On pioche desormais dans douche + hard (donjon/industriel) +
        # WATER_LOCATIONS_DECOR (piscine, cascade, roue d'eau medievale,
        # camping, sauna, labo) pour varier vraiment le lieu d'eau.
        pool = list(SHOWER_ENVIRONMENTS) + list(HARD_ENVIRONMENTS) + list(WATER_LOCATIONS_DECOR)

    elif is_public_context(test_text):
        pool = list(PUBLIC_ENVIRONMENTS)

    else:
        if mode in ["romance", "soft"]:
            base = list(ROMANCE_SOFT_ENVIRONMENTS)
        elif mode == "hard":
            base = list(HARD_ENVIRONMENTS)
        elif mode == "extreme":
            base = list(EXTREME_ENVIRONMENTS)
        else:
            base = list(HARD_ENVIRONMENTS)

        if random.random() < 0.25:
            pool = list(ROOM_THEMES)
        else:
            pool = base + list(ROOM_THEMES)

    if not pool:
        return ""

    # Si la position exige explicitement un lit ("on the bed", "in bed"),
    # exclure le decor exterieur incompatible (parc, plage, foret, rue) --
    # avant, decor et position etaient choisis independamment et pouvaient
    # produire "on the bed" dans un decor de parc.
    needs_bed = re.search(r'\bon the bed\b|\bin bed\b|\bacross the bed\b', test_text, re.I)
    if needs_bed:
        OUTDOOR_WORDS = re.compile(r'\bpark\b|\bforest\b|\bbeach\b|\boutdoor\b|\brooftop\b|\bgarden\b|\bstreet\b', re.I)
        filtered_pool = [d for d in pool if not (isinstance(d, str) and OUTDOOR_WORDS.search(d))]
        if filtered_pool:
            pool = filtered_pool

    decor = random.choice(pool)

    if isinstance(decor, (list, tuple)):
        decor = random.choice(decor) if decor else ""
    if not isinstance(decor, str):
        decor = str(decor) if decor else ""

    return decor.strip()

def get_nudity_dynamic_tag(gender_str, c_type, appearances):
    """
    Injecte un tag Danbooru CFNF/CFNM/CMNF/CMNM selon l'orientation et
    le ratio habille/nu detecte dans les apparences generees.
    Ces tags sont bien compris des modeles (vaste dataset Danbooru).

    Regles par orientation :
    - gay     : CMNM (clothed male, nude male) ou juste nu — pas de genre feminin
    - lesbian : CFNF (clothed female, nude female) — pas de genre masculin
    - hetero  : CFNM (clothed female, nude male) ou CMNF (clothed male, nude female)
                selon qui est habille et qui est nu dans la scene
    """
    if not appearances or not gender_str:
        return ""

    app_lower = appearances.lower()
    has_naked = "naked" in app_lower or "nude" in app_lower or "bottomless" in app_lower
    has_clothed = "wearing" in app_lower

    # Seulement pertinent si mixture habille/nu detectee
    if not (has_naked and has_clothed):
        return ""

    if c_type == "gay":
        return "clothed male, nude male"
    elif c_type == "lesbian":
        return "clothed female, nude female"
    elif c_type == "hetero":
        # Analyser chaque segment "1boy ..." / "1girl ..." separement
        # plutot que de deviner globalement -- l'ancienne version
        # detectait juste la presence du mot "boy" dans gender_str et
        # un etat nu QUELQUE PART dans les apparences, produisant le tag
        # INVERSE des que le mec etait habille et la fille nue (ou l'inverse).
        boy_naked = bool(re.search(r"\d*boy[^,]*?\b(naked|nude|bottomless)\b", app_lower))
        girl_naked = bool(re.search(r"\d*girl[^,]*?\b(naked|nude|bottomless)\b", app_lower))
        if boy_naked and not girl_naked:
            return "clothed female, nude male"
        else:
            return "clothed male, nude female"
    return ""

def adjust_penetration_by_orientation(text, c_type, mode="hard", hetero_anal_chance=0.15):
    """
    Resout les tags generiques sex/vaginal sex/anal sex/fingering selon
    l'orientation, apres translate_tags() et remove_incompatible_tags().

    Pour "lesbian", "anal sex" n'a pas d'equivalent anatomique direct :
    - romance/soft -> converti en "pegging" (strap-on, plus doux)
    - hard/extreme -> converti en "femdom, strap-on anal"
    """
    if not text:
        return text
    if c_type == "gay":
        text = re.sub(r'\bvaginal sex\b', 'anal sex', text, flags=re.I)
        text = BARE_SEX_PATTERN.sub('anal sex', text)
        text = BARE_FINGERING_PATTERN.sub('anal fingering', text)
        text = BARE_FISTING_PATTERN.sub('anal fisting', text)
    elif c_type == "lesbian":
        if mode in ("romance", "soft"):
            text = re.sub(r'\banal sex\b', 'pegging', text, flags=re.I)
        else:
            # "strap-on anal" seul dans le tag -- femdom ajoute separement
            # comme son propre tag pour ne jamais casser le format
            # "(mot:poids)" avec une virgule a l'interieur.
            if re.search(r'\banal sex\b', text, flags=re.I) and '(femdom:' not in text.lower():
                text = f"(femdom:1.3), {text}"
            text = re.sub(r'\banal sex\b', 'strap-on anal', text, flags=re.I)
        text = BARE_SEX_PATTERN.sub('vaginal sex', text)
        text = BARE_FINGERING_PATTERN.sub('vaginal fingering', text)
        text = BARE_FISTING_PATTERN.sub('vaginal fisting', text)
    elif c_type == "hetero":
        text = BARE_SEX_PATTERN.sub('vaginal sex', text)
        if re.search(r'\bvaginal sex\b', text, flags=re.I) and random.random() < hetero_anal_chance:
            text = re.sub(r'\bvaginal sex\b', 'anal sex', text, flags=re.I)
        text = BARE_FINGERING_PATTERN.sub('vaginal fingering', text)
        text = BARE_FISTING_PATTERN.sub('vaginal fisting', text)
    return text


ORIENTATION_CONVERSIONS = {'lesbian': {'double penetration': 'double vaginal', 'triple penetration': 'triple vaginal', 'cum on face': 'squirting on face', 'ejaculation': 'female ejaculation', 'creampie': 'female ejaculation', 'cumshot': 'squirting', 'blowjob': 'cunnilingus', 'irrumatio': 'cunnilingus', 'deepthroat': 'cunnilingus', 'fellatio': 'cunnilingus', 'reverse nursing handjob': 'reverse nursing fingering', 'cuddling handjob': 'cuddling fingering', 'nursing handjob': 'nursing fingering', 'two-handed handjob': 'two-handed fingering', 'cooperative handjob': 'cooperative fingering', 'double handjob': 'double fingering', 'handjob': 'pussyjob', 'paizuri': 'paizuri', 'pecjob': 'paizuri', 'pectoral grab': "grabbing another's breast", 'guided pectoral grab': 'guided breast grab', 'male masturbation': 'female masturbation', 'autofacial': 'squirting', 'muscular male': 'muscular female', 'nantaimori': 'nyotaimori', 'cum on pectorals': 'cum on breasts', 'anal fingering': 'vaginal fingering', 'reach-around': 'reach-around fingering', 'frottage': 'tribadism', 'male penetrated': 'strap-on penetrated', 'crossdressing (mtf)': 'crossdressing (ftm)', 'implied yaoi': 'implied yuri', 'yaoi': 'yuri', 'chastity cage': 'chastity belt'}, 'gay': {'double penetration': 'double anal', 'triple penetration': 'triple anal', 'pegging': 'anal sex', 'cunnilingus': 'fellatio', 'autocunnilingus': 'autofellatio', 'implied cunnilingus': 'implied fellatio', 'paizuri': 'pecjob', 'naizuri': 'pecjob', 'autopaizuri': 'pecjob', 'cooperative paizuri': 'cooperative pecjob', 'pussyjob': 'buttjob', 'cooperative pussyjob': 'cooperative buttjob', 'breast sucking': 'nipple sucking', "grabbing another's breast": 'pectoral grab', 'guided breast grab': 'guided pectoral grab', 'grabbing own breast': 'grabbing own pectorals', 'muscular female': 'muscular male', 'nyotaimori': 'nantaimori', 'cum on breasts': 'cum on pectorals', 'cum on pussy': 'cum on crotch', 'vaginal fingering': 'anal fingering', 'female masturbation': 'male masturbation', 'female ejaculation': 'ejaculation', 'squirting': 'ejaculation', 'crossdressing (ftm)': 'crossdressing (mtf)', 'implied yuri': 'implied yaoi', 'yuri': 'yaoi'}}

DOMINANT_SUB_PATTERN = re.compile(r'\b(subs|sub|dominant)\b', re.IGNORECASE)

def gender_dominant_submissive_terms(text, c_type):
    """
    "sub" en mot nu risque d'etre lu par le modele comme "Subway" ou
    tout autre sens non lie au BDSM -- ce n'est pas un tag reconnu.
    "dominant" seul (adjectif utilise comme nom de personnage) peut se
    lire colle a un autre mot ("dominant light" = terme photo, pas le
    personnage). On remplace par des termes genres et sans ambiguite :
    maledom/femdom (vrais tags Danbooru) ou "submissive man/woman"
    ecrit en toutes lettres.

    "man"/"men" utilises comme label de role (pas dans un mot compose)
    posent un probleme different : si le systeme de swap femdom/maledom
    convertit un des personnages vers le genre oppose, un texte fige
    disant "three men" devient faux (un des trois est maintenant une
    femme). Convertis en "person"/"people", generique et toujours exact
    peu importe la composition finale.
    """
    if not text:
        return text

    has_dom_sub = DOMINANT_SUB_PATTERN.search(text)
    has_man_men = re.search(r'\bman\b|\bmen\b', text, re.IGNORECASE)
    if not has_dom_sub and not has_man_men:
        return text

    if has_dom_sub:
        if c_type == "gay":
            text = re.sub(r'\bsubs\b', 'submissive men', text, flags=re.IGNORECASE)
            text = re.sub(r'\bsub\b', 'submissive man', text, flags=re.IGNORECASE)
            text = re.sub(r'\bdominant\b', 'maledom', text, flags=re.IGNORECASE)
        elif c_type == "lesbian":
            text = re.sub(r'\bsubs\b', 'submissive women', text, flags=re.IGNORECASE)
            text = re.sub(r'\bsub\b', 'submissive woman', text, flags=re.IGNORECASE)
            text = re.sub(r'\bdominant\b', 'femdom', text, flags=re.IGNORECASE)
        else:  # hetero : le genre du dominant varie, on evite le mot seul
            text = re.sub(r'\bsubs\b', 'the submissive ones', text, flags=re.IGNORECASE)
            text = re.sub(r'\bsub\b', 'the submissive', text, flags=re.IGNORECASE)
            text = re.sub(r'\bdominant\b', 'the one in control', text, flags=re.IGNORECASE)

    # man/men -> boy/boys en gay (demande explicite). En hetero, "person"/
    # "people" ne sont pas des tokens du dataset d'entrainement (contrairement
    # a boy/girl/boys/girls) -- choix aleatoire boy ou girl a la place, plus
    # proche du vocabulaire reel que le modele connait.
    if c_type == "gay":
        text = re.sub(r'\bmen\b', 'boys', text)
        text = re.sub(r'\bMen\b', 'Boys', text)
        text = re.sub(r'\bman\b', 'boy', text)
        text = re.sub(r'\bMan\b', 'Boy', text)
    elif c_type == "lesbian":
        text = re.sub(r'\bmen\b', 'girls', text)
        text = re.sub(r'\bMen\b', 'Girls', text)
        text = re.sub(r'\bman\b', 'girl', text)
        text = re.sub(r'\bMan\b', 'Girl', text)
    elif c_type == "hetero":
        plural_word = random.choice(["boys", "girls"])
        singular_word = random.choice(["boy", "girl"])
        text = re.sub(r'\bmen\b', plural_word, text)
        text = re.sub(r'\bMen\b', plural_word.capitalize(), text)
        text = re.sub(r'\bman\b', singular_word, text)
        text = re.sub(r'\bMan\b', singular_word.capitalize(), text)
    else:
        text = re.sub(r'\bmen\b', 'people', text)
        text = re.sub(r'\bMen\b', 'People', text)
        text = re.sub(r'\bman\b', 'person', text)
        text = re.sub(r'\bMan\b', 'Person', text)

    return text


def apply_orientation_conversions(text, c_type):
    """
    Convertit les tags d'une orientation vers leur equivalent dans une autre
    plutot que de simplement les supprimer. Applique AVANT
    remove_incompatible_tags pour ne pas perdre la position.
    """
    if not text or c_type not in ORIENTATION_CONVERSIONS:
        return text
    for old, new in ORIENTATION_CONVERSIONS[c_type].items():
        text = re.sub(rf'\b{re.escape(old)}\b', new, text, flags=re.IGNORECASE)
    return text


# Tags de POSITION PURE (sans acte explicite) qui ont besoin qu'on precise
# l'acte selon l'orientation, sinon le modele reste vague ou hesite.
POSITION_ONLY_TAGS = {
    "missionary position": {
        "gay": "anal sex", "hetero": "vaginal sex",
        "lesbian": "pegging",
    },
}
POSITION_ONLY_PATTERN = re.compile(
    "|".join(rf"\b{re.escape(k)}\b" for k in POSITION_ONLY_TAGS), re.IGNORECASE
)

def ensure_act_tag(text, c_type):
    """
    Si le prompt contient un tag de position pure (ex: missionary position)
    sans mentionner d'acte explicite, on ajoute l'acte correspondant a
    l'orientation. Evite un prompt ambigu que le modele rend au hasard.
    """
    if not text or not POSITION_ONLY_PATTERN.search(str(text)):
        return text
    if re.search(r"\b(anal sex|vaginal sex|pegging|fellatio|cunnilingus)\b", str(text), re.I):
        return text  # acte deja present
    for tag, mapping in POSITION_ONLY_TAGS.items():
        if re.search(rf"\b{re.escape(tag)}\b", str(text), re.I):
            act = mapping.get(c_type)
            if act:
                return f"{text}, ({act}:1.4)"
    return text

def remove_incompatible_tags(prompt, c_type):
    if c_type not in INCOMPATIBLE_KEYWORDS:
        return prompt
    forbidden = INCOMPATIBLE_KEYWORDS[c_type]
    if not forbidden:
        return prompt
    # Suppression par SEGMENT : un tag (delimite par des virgules) qui contient
    # un mot interdit est retire en entier. Evite le bug ou retirer un mot au
    # milieu collait les tags voisins ("exposed nipples, exposed penis" ->
    # "exposedexposed penis").
    patterns = [re.compile(rf'\b{re.escape(w)}\b', re.IGNORECASE) for w in forbidden]

    # Les tokens de genre prefixes d'un chiffre (1girl, 2girls, 3boys...) ne sont
    # PAS attrapes par \b{mot}\b : dans "3girls" il n'y a pas de frontiere de mot
    # entre le chiffre et la lettre. On les traite donc separement.
    if c_type == "gay":
        patterns.append(re.compile(r'\d*\s*girls?\b', re.IGNORECASE))
    elif c_type == "lesbian":
        patterns.append(re.compile(r'\d*\s*boys?\b', re.IGNORECASE))

    segments = [s.strip() for s in prompt.split(',')]
    kept = [s for s in segments if s and not any(p.search(s) for p in patterns)]
    prompt = ", ".join(kept)
    prompt = re.sub(r',\s*,', ',', prompt)
    prompt = re.sub(r'\s{2,}', ' ', prompt).strip(' ,')
    return prompt

