def is_masculine(desc: str) -> bool:
    if not desc:
        return False
    desc_lower = desc.lower()
    masculine_words = ["boy", "male", "man", "men", "guy", "he", "him", "dude", "bro", "gentleman"]
    # \b ne matche PAS dans "2boys" (pas de frontiere entre le chiffre et la
    # lettre, ni entre "boy" et "s"). On autorise donc un chiffre optionnel
    # avant et un pluriel optionnel apres.
    return any(re.search(rf'(?:\b|\d){re.escape(w)}s?\b', desc_lower) for w in masculine_words)


def is_feminine(desc: str) -> bool:
    if not desc:
        return False
    desc_lower = desc.lower()
    feminine_words = ["girl", "female", "woman", "women", "lady", "she", "her", "futa", "shemale"]
    return any(re.search(rf'(?:\b|\d){re.escape(w)}s?\b', desc_lower) for w in feminine_words)


