def get_penis_descriptor(mode: str, force_explicit: bool = False) -> str:
    """
    Retourne un descripteur de pénis aléatoire selon le mode.
    
    Paramètres:
        mode : 'romance', 'soft', 'hard', 'extreme', 'pain'
        force_explicit : force les descripteurs les plus explicites
    """
    if force_explicit or mode == "extreme":
        pool = PENIS_DESCRIPTORS_EXTREME
    elif mode in ["hard", "pain"]:
        pool = PENIS_DESCRIPTORS_HARD
    else:
        pool = PENIS_DESCRIPTORS_SOFT
    
    return random.choice(pool)


def inject_penis_descriptors(line: str, gender: str, mode: str, c_type: str) -> str:
    """
    Desactivable via ENABLE_PENIS_SIZE_SYSTEM en tete de fichier.
    Injecte des descripteurs de pénis pour les personnages masculins.
    
    Règles d'injection:
        - c_type == "gay" ou nb_boys >= 2 : TOUJOURS injecté
        - nb_boys == 1 et mode hard/extreme : 50% de chance
        - nb_boys == 1 et mode pain : 25% de chance
        - nb_boys == 1 et mode romance/soft : 0% de chance
        - Pas de personnage masculin : rien injecté
    
    Paramètres:
        line : le prompt actuel
        gender : chaîne des personnages (ex: "1boy, 1girl")
        mode : mode actuel (romance, soft, hard, extreme, pain)
        c_type : type de contenu (hetero, gay, lesbian)
    
    Retourne:
        Le prompt avec les descripteurs de pénis ajoutés
    """
    if not gender or not line:
        return line
    if not ENABLE_PENIS_SIZE_SYSTEM:
        return line
    
    # Extraire les personnages
    person_descs = parse_gender_string(gender)
    
    # Compter les personnages masculins
    boys = [desc for desc in person_descs if is_masculine(desc)]
    nb_boys = len(boys)
    
    # Si aucun personnage masculin, on ne fait rien
    if nb_boys == 0:
        return line
    
    # Déterminer si on doit injecter
    is_gay = c_type == "gay" or nb_boys >= 2
    is_hard_extreme = mode in ["hard", "extreme"]
    is_pain = mode == "pain"
    
    # Règles d'injection
    if is_gay:
        inject_prob = 1.0  # Toujours
    elif is_hard_extreme and nb_boys == 1:
        inject_prob = 0.50  # 50% de chance
    elif is_pain and nb_boys == 1:
        inject_prob = 0.25  # 25% de chance
    else:
        inject_prob = 0.0   # Jamais
    
    # Tirage aléatoire
    if random.random() > inject_prob:
        return line
    
    # --- Construction du descripteur ---
    force_explicit = mode in ["hard", "extreme"]
    
    if nb_boys >= 2 and is_gay:
        # Pour gay / 2+ boys : un descripteur par personnage
        descriptors = []
        for boy in boys:
            desc = get_penis_descriptor(mode, force_explicit=force_explicit)
            # Ajouter un modificateur d'état aléatoire (40% de chance)
            if random.random() < 0.40:
                state = random.choice(PENIS_STATE_MODIFIERS)
                desc = f"{state} {desc}"
            descriptors.append(desc)
        # Pas de prefixe "{boy}:" : le modele le relit comme un nouveau groupe
        # de personnages et genere des clones. Tags simples separes par virgule.
        penis_tag = ", ".join(descriptors)
    else:
        # Un seul descripteur global ou pour un seul boy
        base_desc = get_penis_descriptor(mode, force_explicit=force_explicit)
        
        # Ajouter un modificateur d'état aléatoire (40% de chance)
        if random.random() < 0.40:
            state = random.choice(PENIS_STATE_MODIFIERS)
            base_desc = f"{state} {base_desc}"
        
        # Jamais de prefixe "{boys[0]}:" -> genere des clones
        penis_tag = base_desc
    
    # Éviter les doublons (si déjà présent dans le prompt)
    # On vérifie si une version simplifiée est déjà présente
    check_terms = ["penis", "penis", "dick"]
    if any(term in line.lower() for term in check_terms):
        # Si déjà présent, on ne l'ajoute pas (évite les doublons)
        # Mais on peut quand même ajouter si c'est un descripteur plus précis
        # Pour simplifier, on ne l'ajoute pas
        return line
    
    # Ajouter à la fin du prompt
    return line + f", {penis_tag}"
