def translate_tags(text: str) -> str:
    if not text:
        return text
    mapping = globals().get("TAG_MAPPING", {}) or {}
    # longues clés d'abord
    items = sorted(mapping.items(), key=lambda kv: len(kv[0]), reverse=True)
    out = text
    for src, dst in items:
        out = out.replace(src, dst)
    return out
def write_csv_metadata(metadata_list, filename="Bedroom_Categories.csv"):
    if not metadata_list:
        print("⚠️ Aucune metadata à écrire")
        return

    fieldnames = ["name", "tab", "grid", "items", "order", "image_url"]
    filepath = Path(filename)

    with open(filepath, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for row in metadata_list:
            writer.writerow({
                "name": row.get("name", ""),
                "tab": row.get("tab", ""),
                "grid": row.get("grid", ""),
                "items": row.get("items", ""),
                "order": row.get("order", 0),
                "image_url": row.get("image_url", ""),
            })

    print(f"✅ CSV écrit : {filepath} ({len(metadata_list)} lignes)")

