GENDER_TOKEN_PATTERN = re.compile(r'^\d+(?:boy|girl)s?$', re.IGNORECASE)

def is_too_similar(new_prompt, recent_prompts, max_similar=3):
    if not recent_prompts:
        return False
    skip_patterns = re.compile(
        r"^\d+(?:boy|girl)s?$|shot|view|pov|angle|close-up|full-body|medium|cowboy",
        re.IGNORECASE
    )
    def key_tags(prompt):
        tags = [t.strip().lower() for t in prompt.split(", ") if t.strip()]
        return set([t for t in tags if not skip_patterns.search(t)][:4])
    new_keys = key_tags(new_prompt)
    if not new_keys:
        return False
    similar_count = 0
    for recent in recent_prompts[-50:]:
        if len(new_keys & key_tags(recent)) >= max_similar:
            similar_count += 1
            if similar_count >= 3:
                return True
    return False

